function splitName(fullName: string): { fname: string; lname: string } {
  const parts = fullName.trim().split(/\s+/);
  if (parts.length <= 1) {
    return { fname: fullName.trim(), lname: '' };
  }
  return {
    fname: parts[0],
    lname: parts.slice(1).join(' '),
  };
}

