export const INITIAL_PERSONNEL: Personnel[] = RAW_GUARD_DATA.map((item, idx) => {
  const { fname, lname } = splitName(item.full_name);
  return {
    db_id: item.id,
    id: item.employee_id,
    fname,
    lname,
    gender: item.gender as 'M' | 'F',
    position: item.position,
    dept: item.department,
    status: 'active',
    canDuty: item.can_duty === 1,
    isInspector: item.is_inspector === 1,
    dutyPoint: item.dutyPoint || '',
    pairNo: item.pairNo || '',
    orderIndex: item.orderIndex || idx + 1,
  };
});

export const INITIAL_EMPLOYEE_DIRECTORY: EmployeeDirectoryItem[] = INITIAL_PERSONNEL.map(p => ({
  employee_id: p.id,
  full_name_thai: `${p.fname} ${p.lname}`.trim(),
  gender: p.gender,
  position_thai: p.position,
  dept: p.dept,
}));
